import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { ArrowLeft, Phone, MapPin, Clock, Send, CheckCircle } from 'lucide-react';
import { Link } from 'react-router-dom';
import Button from '../../components/Button';

/**
 * ContactPage Component
 *
 * Displays contact information and a contact form.
 */
const ContactPage: React.FC = () => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    message: '',
  });
  const [isSubmitted, setIsSubmitted] = useState(false);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // Simulate form submission
    setIsSubmitted(true);
    setTimeout(() => setIsSubmitted(false), 3000);
    setFormData({ name: '', email: '', message: '' });
  };

  return (
    <div className="min-h-screen bg-cream-200 dark:bg-secondary-500">
      {/* Header */}
      <header className="sticky top-0 z-50 glass border-b border-secondary-200/20 dark:border-secondary-400/20">
        <div className="container-custom py-4">
          <div className="flex items-center gap-4">
            <Link to="/" className="p-2 rounded-full hover:bg-secondary-100 dark:hover:bg-secondary-500 transition-colors">
              <ArrowLeft className="w-6 h-6 text-secondary-500 dark:text-cream-200" />
            </Link>
            <span className="text-xl font-heading font-bold text-secondary-500 dark:text-cream-200">
              Contact Us
            </span>
          </div>
        </div>
      </header>

      {/* Hero Section */}
      <section className="relative py-20 bg-gradient-to-br from-primary-400 to-primary-500">
        <div className="container-custom text-center">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
          >
            <h1 className="text-4xl md:text-6xl font-heading font-bold text-white mb-6">
              Get in Touch
            </h1>
            <p className="text-xl text-white/90 max-w-2xl mx-auto">
              We'd love to hear from you. Reach out for reservations, feedback, or just to say hello!
            </p>
          </motion.div>
        </div>
      </section>

      {/* Contact Info Cards */}
      <section className="py-20">
        <div className="container-custom">
          <div className="grid md:grid-cols-3 gap-8 mb-20">
            {[
              { icon: Phone, title: 'Phone', info: '+251 911 234 567', subInfo: 'Mon-Sun 7AM-11PM' },
              { icon: MapPin, title: 'Location', info: 'Cinema Building', subInfo: 'Addis Ababa, Ethiopia' },
              { icon: Clock, title: 'Hours', info: '7:00 AM - 11:00 PM', subInfo: 'Open Every Day' },
            ].map((item, index) => (
              <motion.div
                key={item.title}
                initial={{ opacity: 0, y: 20 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ delay: index * 0.1 }}
                className="bg-white dark:bg-secondary-400 rounded-2xl p-8 text-center shadow-card"
              >
                <div className="w-16 h-16 mx-auto mb-4 bg-primary-400 rounded-2xl flex items-center justify-center">
                  <item.icon className="w-8 h-8 text-white" />
                </div>
                <h3 className="text-xl font-heading font-semibold text-secondary-500 dark:text-cream-200 mb-2">
                  {item.title}
                </h3>
                <p className="text-secondary-500 dark:text-cream-200 font-medium">
                  {item.info}
                </p>
                <p className="text-secondary-400 dark:text-cream-300 text-sm">
                  {item.subInfo}
                </p>
              </motion.div>
            ))}
          </div>

          {/* Contact Form */}
          <div className="max-w-2xl mx-auto">
            <motion.div
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              className="bg-white dark:bg-secondary-400 rounded-3xl p-8 md:p-12 shadow-card"
            >
              <h2 className="text-3xl font-heading font-bold text-secondary-500 dark:text-cream-200 mb-8 text-center">
                Send us a Message
              </h2>

              {isSubmitted ? (
                <div className="text-center py-12">
                  <CheckCircle className="w-16 h-16 text-green-500 mx-auto mb-4" />
                  <h3 className="text-2xl font-heading font-semibold text-secondary-500 dark:text-cream-200 mb-2">
                    Message Sent!
                  </h3>
                  <p className="text-secondary-400 dark:text-cream-300">
                    We'll get back to you soon.
                  </p>
                </div>
              ) : (
                <form onSubmit={handleSubmit} className="space-y-6">
                  <div>
                    <label className="block text-sm font-medium text-secondary-500 dark:text-cream-200 mb-2">
                      Your Name
                    </label>
                    <input
                      type="text"
                      value={formData.name}
                      onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                      className="w-full px-4 py-3 rounded-xl border border-secondary-200 dark:border-secondary-300 bg-cream-100 dark:bg-secondary-500 text-secondary-500 dark:text-cream-200 focus:outline-none focus:ring-2 focus:ring-primary-400"
                      placeholder="John Doe"
                      required
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-secondary-500 dark:text-cream-200 mb-2">
                      Email Address
                    </label>
                    <input
                      type="email"
                      value={formData.email}
                      onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                      className="w-full px-4 py-3 rounded-xl border border-secondary-200 dark:border-secondary-300 bg-cream-100 dark:bg-secondary-500 text-secondary-500 dark:text-cream-200 focus:outline-none focus:ring-2 focus:ring-primary-400"
                      placeholder="john@example.com"
                      required
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-secondary-500 dark:text-cream-200 mb-2">
                      Message
                    </label>
                    <textarea
                      value={formData.message}
                      onChange={(e) => setFormData({ ...formData, message: e.target.value })}
                      rows={5}
                      className="w-full px-4 py-3 rounded-xl border border-secondary-200 dark:border-secondary-300 bg-cream-100 dark:bg-secondary-500 text-secondary-500 dark:text-cream-200 focus:outline-none focus:ring-2 focus:ring-primary-400 resize-none"
                      placeholder="How can we help you?"
                      required
                    />
                  </div>

                  <Button
                    type="submit"
                    variant="primary"
                    size="lg"
                    className="w-full"
                    leftIcon={<Send className="w-5 h-5" />}
                  >
                    Send Message
                  </Button>
                </form>
              )}
            </motion.div>
          </div>
        </div>
      </section>

      {/* Map Section (Placeholder) */}
      <section className="py-20 bg-white dark:bg-secondary-400">
        <div className="container-custom">
          <div className="text-center mb-12">
            <h2 className="text-3xl font-heading font-bold text-secondary-500 dark:text-cream-200 mb-4">
              Find Us
            </h2>
            <p className="text-secondary-400 dark:text-cream-300">
              Located in the heart of Addis Ababa's cinema district
            </p>
          </div>
          <div className="bg-cream-100 dark:bg-secondary-500 rounded-3xl h-96 flex items-center justify-center">
            <div className="text-center">
              <MapPin className="w-16 h-16 text-primary-400 mx-auto mb-4" />
              <p className="text-secondary-500 dark:text-cream-200 font-medium">
                Cinema Building, Addis Ababa
              </p>
              <p className="text-secondary-400 dark:text-cream-300">
                Near Edna Mall
              </p>
            </div>
          </div>
        </div>
      </section>

      {/* Footer */}
      <footer className="bg-secondary-600 py-8">
        <div className="container-custom text-center">
          <p className="text-cream-400 text-sm">
            © 2024 Cinema Cafe. All rights reserved.
          </p>
        </div>
      </footer>
    </div>
  );
};

export default ContactPage;
