import React from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { ArrowLeft, Clock, Flame, Leaf, Plus, Minus, ShoppingCart } from 'lucide-react';
import { getItemById, menuItems } from '../../data/menuData';
import { getCategoryById } from '../../data/categories';
import Button from '../../components/Button';

/**
 * ItemDetailPage Component
 * 
 * Displays detailed information about a specific menu item.
 */
const ItemDetailPage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [quantity, setQuantity] = React.useState(1);

  const item = id ? getItemById(id) : undefined;

  if (!item) {
    return (
      <div className="min-h-screen bg-cream-200 dark:bg-secondary-500 flex items-center justify-center">
        <div className="text-center">
          <div className="text-6xl mb-4">😕</div>
          <h1 className="text-2xl font-heading font-bold text-secondary-500 dark:text-cream-200 mb-4">
            Item Not Found
          </h1>
          <Link to="/menu">
            <Button variant="primary">Back to Menu</Button>
          </Link>
        </div>
      </div>
    );
  }

  const category = getCategoryById(item.category);

  // Get related items from same category
  const relatedItems = menuItems
    .filter((i) => i.category === item.category && i.id !== item.id)
    .slice(0, 4);

  return (
    <div className="min-h-screen bg-cream-200 dark:bg-secondary-500">
      {/* Header */}
      <header className="sticky top-0 z-50 glass border-b border-secondary-200/20 dark:border-secondary-400/20">
        <div className="container-custom py-4">
          <div className="flex items-center gap-4">
            <button
              onClick={() => navigate(-1)}
              className="p-2 rounded-full hover:bg-secondary-100 dark:hover:bg-secondary-500 transition-colors"
            >
              <ArrowLeft className="w-6 h-6 text-secondary-500 dark:text-cream-200" />
            </button>
            <span className="text-lg font-medium text-secondary-500 dark:text-cream-200">
              {category?.name || 'Menu Item'}
            </span>
          </div>
        </div>
      </header>

      {/* Item Details */}
      <section className="container-custom py-8">
        <div className="max-w-4xl mx-auto">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="bg-white dark:bg-secondary-400 rounded-3xl overflow-hidden shadow-card"
          >
            {/* Hero Image */}
            <div className="h-64 sm:h-80 bg-gradient-to-br from-primary-300 to-primary-500 flex items-center justify-center">
              <div className="text-8xl">
                {item.category === 'breakfast' && '🍳'}
                {item.category === 'salad' && '🥗'}
                {item.category === 'burger' && '🍔'}
                {item.category === 'pizza' && '🍕'}
                {item.category === 'sandwich' && '🥪'}
                {item.category === 'bread' && '🥐'}
                {item.category === 'cake' && '🍰'}
                {item.category === 'pasta' && '🍝'}
                {item.category === 'drinks' && '☕'}
              </div>
            </div>

            {/* Content */}
            <div className="p-6 sm:p-8">
              {/* Title and Price */}
              <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-4 mb-6">
                <div>
                  <h1 className="text-3xl sm:text-4xl font-heading font-bold text-secondary-500 dark:text-cream-200 mb-2">
                    {item.name}
                  </h1>
                  <p className="text-secondary-400 dark:text-cream-300">
                    {item.nameAm}
                  </p>
                </div>
                <div className="text-3xl sm:text-4xl font-bold text-primary-500">
                  {item.price} ETB
                </div>
              </div>

              {/* Badges */}
              <div className="flex flex-wrap gap-2 mb-6">
                {item.isPopular && (
                  <span className="bg-accent/20 text-accent px-3 py-1 rounded-full text-sm font-medium">
                    Popular
                  </span>
                )}
                {item.isNew && (
                  <span className="bg-green-500/20 text-green-500 px-3 py-1 rounded-full text-sm font-medium">
                    New
                  </span>
                )}
                {item.dietary?.map((diet) => (
                  <span
                    key={diet}
                    className="bg-primary-400/10 text-primary-500 px-3 py-1 rounded-full text-sm font-medium flex items-center gap-1"
                  >
                    {diet === 'vegetarian' && <Leaf className="w-4 h-4" />}
                    {diet === 'vegan' && <Leaf className="w-4 h-4" />}
                    {diet === 'spicy' && <Flame className="w-4 h-4" />}
                    {diet}
                  </span>
                ))}
              </div>

              {/* Description */}
              <div className="mb-8">
                <h2 className="text-xl font-heading font-semibold text-secondary-500 dark:text-cream-200 mb-3">
                  Description
                </h2>
                <p className="text-secondary-400 dark:text-cream-300 leading-relaxed">
                  {item.description}
                </p>
                <p className="text-secondary-400 dark:text-cream-300 mt-2">
                  {item.descriptionAm}
                </p>
              </div>

              {/* Details */}
              <div className="flex flex-wrap gap-6 mb-8 pb-8 border-b border-secondary-200/20 dark:border-secondary-400/20">
                {item.prepTime && (
                  <div className="flex items-center gap-2 text-secondary-400 dark:text-cream-300">
                    <Clock className="w-5 h-5" />
                    <span>{item.prepTime} mins prep time</span>
                  </div>
                )}
                {item.calories && (
                  <div className="flex items-center gap-2 text-secondary-400 dark:text-cream-300">
                    <Flame className="w-5 h-5" />
                    <span>{item.calories} calories</span>
                  </div>
                )}
              </div>

              {/* Quantity and Add to Cart */}
              <div className="flex flex-col sm:flex-row items-center gap-4">
                {/* Quantity Selector */}
                <div className="flex items-center gap-4 bg-cream-100 dark:bg-secondary-500 rounded-xl p-2">
                  <button
                    onClick={() => setQuantity(Math.max(1, quantity - 1))}
                    className="w-10 h-10 rounded-lg bg-white dark:bg-secondary-400 flex items-center justify-center text-secondary-500 dark:text-cream-200 hover:bg-primary-400 hover:text-white transition-colors"
                  >
                    <Minus className="w-5 h-5" />
                  </button>
                  <span className="w-12 text-center text-xl font-semibold text-secondary-500 dark:text-cream-200">
                    {quantity}
                  </span>
                  <button
                    onClick={() => setQuantity(quantity + 1)}
                    className="w-10 h-10 rounded-lg bg-white dark:bg-secondary-400 flex items-center justify-center text-secondary-500 dark:text-cream-200 hover:bg-primary-400 hover:text-white transition-colors"
                  >
                    <Plus className="w-5 h-5" />
                  </button>
                </div>

                {/* Add to Cart Button */}
                <Button
                  variant="primary"
                  size="lg"
                  className="flex-1 w-full sm:w-auto"
                  leftIcon={<ShoppingCart className="w-5 h-5" />}
                >
                  Add to Cart - {item.price * quantity} ETB
                </Button>
              </div>
            </div>
          </motion.div>

          {/* Related Items */}
          {relatedItems.length > 0 && (
            <div className="mt-12">
              <h2 className="text-2xl font-heading font-bold text-secondary-500 dark:text-cream-200 mb-6">
                You Might Also Like
              </h2>
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                {relatedItems.map((relatedItem) => (
                  <Link key={relatedItem.id} to={`/menu/${relatedItem.id}`}>
                    <div className="bg-white dark:bg-secondary-400 rounded-2xl overflow-hidden shadow-card hover:shadow-card-hover transition-all">
                      <div className="h-32 bg-gradient-to-br from-primary-300 to-primary-500 flex items-center justify-center">
                        <div className="text-4xl">
                          {relatedItem.category === 'breakfast' && '🍳'}
                          {relatedItem.category === 'salad' && '🥗'}
                          {relatedItem.category === 'burger' && '🍔'}
                          {relatedItem.category === 'pizza' && '🍕'}
                          {relatedItem.category === 'sandwich' && '🥪'}
                          {relatedItem.category === 'bread' && '🥐'}
                          {relatedItem.category === 'cake' && '🍰'}
                          {relatedItem.category === 'pasta' && '🍝'}
                          {relatedItem.category === 'drinks' && '☕'}
                        </div>
                      </div>
                      <div className="p-4">
                        <h3 className="font-semibold text-secondary-500 dark:text-cream-200 text-sm mb-1">
                          {relatedItem.name}
                        </h3>
                        <p className="text-primary-500 font-bold">
                          {relatedItem.price} ETB
                        </p>
                      </div>
                    </div>
                  </Link>
                ))}
              </div>
            </div>
          )}
        </div>
      </section>

      {/* Footer */}
      <footer className="bg-secondary-600 py-8 mt-12">
        <div className="container-custom text-center">
          <p className="text-cream-400 text-sm">
            © 2024 Cinema Cafe. All rights reserved.
          </p>
        </div>
      </footer>
    </div>
  );
};

export default ItemDetailPage;
