/**
 * Get category by ID
 */
export function getCategoryById(id: string): Category | undefined {
  return categories.find((cat) => cat.id === id);
}

/**
 * Get category name based on language
 */
export function getCategoryName(category: Category, language: 'en' | 'am'): string {
  return language === 'am' ? category.nameAm : category.name;
}
