/**
 * Get menu items by category
 */
export function getItemsByCategory(categoryId: string): MenuItem[] {
  return menuItems.filter((item) => item.category === categoryId);
}

/**
 * Get popular items
 */
export function getPopularItems(): MenuItem[] {
  return menuItems.filter((item) => item.isPopular);
}

/**
 * Get new items
 */
export function getNewItems(): MenuItem[] {
  return menuItems.filter((item) => item.isNew);
}

/**
 * Get item by ID
 */
export function getItemById(id: string): MenuItem | undefined {
  return menuItems.find((item) => item.id === id);
}

/**
 * Search menu items
 */
export function searchItems(query: string): MenuItem[] {
  const lowercaseQuery = query.toLowerCase();
  return menuItems.filter(
    (item) =>
      item.name.toLowerCase().includes(lowercaseQuery) ||
      item.nameAm.toLowerCase().includes(lowercaseQuery) ||
      item.description.toLowerCase().includes(lowercaseQuery)
  );
}
